// Pega os valores mínimo e máximo do delay
const delayMinimo = $('Validação de Horário').first().json.delay_minimo_mensagens;
const delayMaximo = $('Validação de Horário').first().json.delay_maximo_mensagens;

// Valida se os valores são números válidos
if (!delayMinimo || !delayMaximo || isNaN(delayMinimo) || isNaN(delayMaximo)) {
  throw new Error('Valores de delay mínimo e máximo devem ser números válidos');
}

// Converte para números (caso venham como string)
const min = Number(delayMinimo);
const max = Number(delayMaximo);

// Valida se mínimo é menor que máximo
if (min > max) {
  throw new Error('Delay mínimo não pode ser maior que o máximo');
}

// Gera um número aleatório entre min e max (inclusive)
const delayAleatorio = Math.floor(Math.random() * (max - min + 1)) + min;

return [
  {
    json: {
      delay_gerado: delayAleatorio,
    }
  }
];

